package cn.zhuatech.mdm;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.*;import java.util.regex.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class DeepMasterDataOpsTests{@Autowired MockMvc mvc;String token;@BeforeEach void auth()throws Exception{String j=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"admin\",\"password\":\"admin123\"}")).andReturn().getResponse().getContentAsString();var m=Pattern.compile("\\\"token\\\":\\\"([^\\\"]+)\\\"").matcher(j);Assertions.assertTrue(m.find());token=m.group(1);}
 @Test void goldenRecordMergeAndChangeDistributionCloseLoop()throws Exception{long d=domain("SUP-A");long a=record(d,"REC-A1","统一供应商","91310001");call("/api/mdm-ops/records/"+a+"/submit","{}");admin("/api/admin/mdm-ops/records/"+a+"/steward","{\"decision\":\"CREATE_GOLDEN\",\"goldenRecordId\":null}");long b=record(d,"REC-A2","统一 供应商","91310001");call("/api/mdm-ops/records/"+b+"/submit","{}").andExpect(jsonPath("$.data.candidateCount").value(1));admin("/api/admin/mdm-ops/records/"+b+"/steward","{\"decision\":\"MERGE\",\"goldenRecordId\":"+a+"}").andExpect(jsonPath("$.data.status").value("MERGED"));long c=id(call("/api/mdm-ops/changes","{\"changeNo\":\"CHG-A\",\"goldenRecordId\":"+a+",\"fieldName\":\"name\",\"newValue\":\"统一供应商集团\",\"reason\":\"工商更名\"}").andReturn());admin("/api/admin/mdm-ops/changes/"+c+"/approve","{\"approved\":true,\"targetSystem\":\"ERP\"}");mvc.perform(get("/api/mdm-ops/workspace").header("Authorization","Bearer "+token)).andExpect(jsonPath("$.data.outbox[0].status").value("PENDING"));}
 @Test void draftDomainRejectsIngestion()throws Exception{long d=id(admin("/api/admin/mdm-ops/domains","{\"domainCode\":\"DRAFT-A\",\"name\":\"草稿域\",\"keyField\":\"code\",\"matchThreshold\":80}").andReturn());call("/api/mdm-ops/domains/"+d+"/records","{\"recordNo\":\"X\",\"sourceSystem\":\"ERP\",\"businessKey\":\"X\",\"name\":\"测试\",\"identityNo\":\"X\"}").andExpect(status().isConflict());}
 @Test void nonGoldenRecordCannotChange()throws Exception{long d=domain("MAT-A");long r=record(d,"REC-X","物料A","M001");call("/api/mdm-ops/changes","{\"changeNo\":\"CHG-X\",\"goldenRecordId\":"+r+",\"fieldName\":\"name\",\"newValue\":\"物料B\",\"reason\":\"测试\"}").andExpect(status().isConflict());}
 long domain(String c)throws Exception{long d=id(admin("/api/admin/mdm-ops/domains","{\"domainCode\":\""+c+"\",\"name\":\"供应商主数据\",\"keyField\":\"identityNo\",\"matchThreshold\":80}").andReturn());admin("/api/admin/mdm-ops/domains/"+d+"/activate","{}");return d;}long record(long d,String no,String name,String tax)throws Exception{return id(call("/api/mdm-ops/domains/"+d+"/records","{\"recordNo\":\""+no+"\",\"sourceSystem\":\"SRM\",\"businessKey\":\""+no+"\",\"name\":\""+name+"\",\"identityNo\":\""+tax+"\"}").andReturn());}ResultActions call(String u,String b)throws Exception{return mvc.perform(post(u).header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content(b));}ResultActions admin(String u,String b)throws Exception{return call(u,b);}long id(MvcResult r)throws Exception{var m=Pattern.compile("\"id\":(\\d+)").matcher(r.getResponse().getContentAsString());Assertions.assertTrue(m.find());return Long.parseLong(m.group(1));}}
